import { test, expect } from '@playwright/test';

test.describe('Print Filtered Table View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should print a filtered table view with correct data', async ({ page }) => {
    // Filter the table by entering a search term
    const searchInput = page.getByPlaceholder('Search table...');
    await searchInput.fill('active');

    // Wait for the table to update with filtered results
    await page.waitForResponse(response => 
      response.url().includes('/api/table/data') && response.status() === 200
    );

    // Verify the table displays filtered results
    const tableBody = page.getByRole('row', { name: /active/i });
    await expect(tableBody).toBeVisible();

    // Verify the table has at least one row
    const rows = page.getByRole('row');
    const rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(0);

    // Click the print button
    const printButton = page.getByRole('button', { name: /print table/i });
    await printButton.click();

    // Wait for the print dialog to appear
    await page.waitForTimeout(500);

    // Verify the print dialog is visible
    const printDialog = page.locator('[data-testid="print-dialog"]');
    await expect(printDialog).toBeVisible();

    // Verify the print preview shows the filtered data
    const printPreview = page.locator('[data-testid="print-preview"]');
    await expect(printPreview).toContainText('active');
    await expect(printPreview).toContainText('filtered results');

    // Verify the print button is disabled after printing
    await expect(printButton).toBeDisabled();
  });

  test('should handle empty filter results and print gracefully', async ({ page }) => {
    // Filter the table with a non-existent term
    const searchInput = page.getByPlaceholder('Search table...');
    await searchInput.fill('nonexistentterm123');

    // Wait for the table to update
    await page.waitForResponse(response => 
      response.url().includes('/api/table/data') && response.status() === 200
    );

    // Verify the table shows no results
    const tableBody = page.getByRole('row');
    const rowCount = await tableBody.count();
    expect(rowCount).toBe(0);

    // Verify the no results message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Click the print button
    const printButton = page.getByRole('button', { name: /print table/i });
    await printButton.click();

    // Wait for the print dialog to appear
    await page.waitForTimeout(500);

    // Verify the print dialog is visible
    const printDialog = page.locator('[data-testid="print-dialog"]');
    await expect(printDialog).toBeVisible();

    // Verify the print preview shows the no results message
    const printPreview = page.locator('[data-testid="print-preview"]');
    await expect(printPreview).toContainText('No results found');

    // Verify the print button is re-enabled after handling empty results
    await expect(printButton).not.toBeDisabled();
  });
});
